23	    public CheckoutResponse calcularResumo(CheckoutRequest request) {
24	        try {
25	            validarRequest(request);
26	
27	            BigDecimal subtotalProdutos = calcularSubtotal(request.getItens());
28	
29	            CupomStrategy cupomStrategy = CupomFactory.criar(request.getCupom());
30	            BigDecimal descontoCupom = BigDecimal.ZERO;
31	            boolean isFreteGratis = false;
32	
33	            if (cupomStrategy != null) {
34	                cupomStrategy.validar(subtotalProdutos);
35	                if ("FRETEGRATIS".equals(request.getCupom())) {
36	                    isFreteGratis = true;
37	                } else {
38	                    descontoCupom = cupomStrategy.calcularDesconto(subtotalProdutos, request);
39	                }
40	            }
41	
42	            double pesoTotal = calcularPesoTotal(request.getItens());
43	            ModalidadeEntregaStrategy entregaStrategy = ModalidadeEntregaFactory.criar(request.getModalidadeEntrega());
44	            entregaStrategy.validar(pesoTotal);
45	
46	            ClubeMemberStrategy clubeStrategy = ClubeMemberFactory.criar(request.getNivelClube());
47	            boolean temFreteGratisClube = clubeStrategy.temFreteGratis();
48	
49	            BigDecimal frete = BigDecimal.ZERO;
50	            int prazoEntrega = entregaStrategy.getPrazoEntregaDias();
51	
52	            if (!isFreteGratis && !temFreteGratisClube) {
53	                frete = entregaStrategy.calcularFrete(pesoTotal);
54	            } else if (isFreteGratis) {
55	                descontoCupom = entregaStrategy.calcularFrete(pesoTotal);
56	            }
57	
58	            BigDecimal totalAntesDoSeguro = subtotalProdutos
59	                .subtract(descontoCupom)
60	                .add(frete);
61	
62	            BigDecimal seguro = calcularSeguro(subtotalProdutos, request.getRegiao());
63	
64	            BigDecimal totalAntesAjuste = totalAntesDoSeguro.add(seguro);
65	
66	            Integer parcelas = request.getParcelas() != null ? request.getParcelas() : 1;
67	            FormaPagamentoStrategy pagamentoStrategy = FormaPagamentoFactory.criar(request.getFormaPagamento());
68	            pagamentoStrategy.validar(totalAntesAjuste, parcelas);
69	
70	            BigDecimal ajustePagamento = pagamentoStrategy.calcularAjuste(totalAntesAjuste, parcelas);
71	            BigDecimal totalFinal = totalAntesAjuste.add(ajustePagamento);
72	
73	            BigDecimal valorParcela = MoneyRounder.round(totalFinal.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
74	
75	            BigDecimal credito = clubeStrategy.calcularCredito(subtotalProdutos);
76	            boolean brinde = clubeStrategy.validarBrinde(subtotalProdutos);
77	
78	            CheckoutResponse response = new CheckoutResponse();
79	            response.setSubtotalProdutos(subtotalProdutos);
80	            response.setDescontoCupom(descontoCupom);
81	            response.setFrete(frete);
82	            response.setPrazoEntregaDias(prazoEntrega);
83	            response.setSeguro(seguro);
84	            response.setAjustePagamento(ajustePagamento);
85	            response.setTotalFinal(totalFinal);
86	            response.setParcelas(parcelas);
87	            response.setValorParcela(valorParcela);
88	            response.setCreditoProximaCompra(credito);
89	            response.setBrinde(brinde);
90	
91	            return response;
92	        } catch (CheckoutException e) {
93	            throw e;
94	        }
95	    }
96	
97	    private void validarRequest(CheckoutRequest request) {
98	        if (request.getItens() == null || request.getItens().isEmpty()) {
99	            throw new CheckoutException("PEDIDO_INVALIDO");
100	        }
101	
102	        for (Item item : request.getItens()) {
103	            if (item.getPrecoUnitario() == null || item.getPrecoUnitario() <= 0 ||
104	                item.getQuantidade() == null || item.getQuantidade() <= 0 ||
105	                item.getPesoKg() == null || item.getPesoKg() <= 0) {
106	                throw new CheckoutException("PEDIDO_INVALIDO");
107	            }
108	        }
109	
110	        if (request.getNivelClube() == null) {
111	            throw new CheckoutException("NIVEL_CLUBE_INVALIDO");
112	        }
113	
114	        if (request.getRegiao() == null) {
115	            throw new CheckoutException("REGIAO_INVALIDA");
116	        }
117	
118	        if (request.getModalidadeEntrega() == null) {
119	            throw new CheckoutException("MODALIDADE_INVALIDA");
120	        }
121	
122	        if (request.getFormaPagamento() == null) {
123	            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
124	        }
125	    }
126	
127	    private BigDecimal calcularSubtotal(List<Item> itens) {
128	        BigDecimal subtotal = BigDecimal.ZERO;
129	        for (Item item : itens) {
130	            BigDecimal valorItem = BigDecimal.valueOf(item.getPrecoUnitario() * item.getQuantidade());
131	            subtotal = subtotal.add(valorItem);
132	        }
133	        return MoneyRounder.round(subtotal);
134	    }
135	
136	    private double calcularPesoTotal(List<Item> itens) {
137	        double peso = 0;
138	        for (Item item : itens) {
139	            peso += item.getPesoKg() * item.getQuantidade();
140	        }
141	        return peso;
142	    }
143	
144	    private BigDecimal calcularSeguro(BigDecimal subtotalProdutos, com.loja.checkout.model.Region regiao) {
145	        double percentual = regiao.getInsurancePercentage();
146	        return MoneyRounder.round(subtotalProdutos.multiply(BigDecimal.valueOf(percentual)));
147	    }
