        assertEquals(BigDecimal.valueOf(39.80), response.getDescontoCupom());
        assertEquals(BigDecimal.valueOf(0.00), response.getFrete());
        assertEquals(1, response.getPrazoEntregaDias());
        assertEquals(BigDecimal.valueOf(2.99), response.getSeguro());
        assertEquals(3, response.getParcelas());
        assertEquals(BigDecimal.valueOf(5.98), response.getCreditoProximaCompra());
        assertEquals(false, response.getBrinde());
    }

    @Test
    public void exemplo5() {
        CheckoutRequest request = new CheckoutRequest();
        request.setItens(Arrays.asList(
            new Item("Camiseta", 79.90, 2, 0.30),
            new Item("Tênis", 249.90, 1, 1.20)
        ));
        request.setModalidadeEntrega(ModalidadeEntrega.EXPRESSA);
        request.setCupom(null);
        request.setFormaPagamento(FormaPagamento.PIX);
        request.setParcelas(1);
        request.setNivelClube(NivelClube.OURO);
        request.setRegiao(Region.SUDESTE);

        CheckoutResponse response = checkoutService.calcularResumo(request);

        assertEquals(BigDecimal.valueOf(409.70), response.getSubtotalProdutos());
        assertEquals(BigDecimal.valueOf(0.00), response.getDescontoCupom());
        assertEquals(BigDecimal.valueOf(0.00), response.getFrete());
        assertEquals(2, response.getPrazoEntregaDias());
        assertEquals(BigDecimal.valueOf(4.10), response.getSeguro());
        assertEquals(BigDecimal.valueOf(-20.48), response.getAjustePagamento());
        assertEquals(BigDecimal.valueOf(393.32), response.getTotalFinal());
    }
}

